import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"艮其背","description":"周易集解 - 艮其背","frontmatter":{"title":"艮其背","description":"周易集解 - 艮其背"},"headers":[],"relativePath":"zh/classics/jijie/052.md","filePath":"zh/classics/jijie/052.md"}'),l={name:"zh/classics/jijie/052.md"};function n(d,a,t,s,p,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="艮其背" tabindex="-1">艮其背 <a class="header-anchor" href="#艮其背" aria-label="Permalink to “艮其背”">​</a></h1><h2 id="艮其背-1" tabindex="-1">艮其背 <a class="header-anchor" href="#艮其背-1" aria-label="Permalink to “艮其背”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>艮其背，不獲其身，行其庭，不見其人，無咎。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《序卦》曰：物不可以終動，動必止之，故受之以艮。艮者，止也。</p><p>崔憬曰：震極則徵凶。婚媾有言，當須止之。故言｢物不可以終動，止之｣矣。</p><p>鄭玄曰：艮為山。山立峙各於其所，無相順之時。猶君在上，臣在下，恩敬不相與通，故謂之艮也。</p><p>虞翻曰：觀五之三也。艮為多節，故稱｢背｣。觀坤為身，觀五之三，折坤為背，故｢艮其背｣。坤象不見，故｢不獲其身｣。震為行人，艮為庭，坎為隱伏，故｢行其庭，不見其人｣。三得正，故無咎。</p><p>案：艮為門闕，今純艮，重其門闕。兩門之間，庭中之象也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：艮，止也。時止則止，時行則行，動靜不失其時，其道光明。艮其止，止其所也。上下敵應，不相與也。是以不獲其身，行其庭，不見其人，無咎也。</p><h2 id="彖传注" tabindex="-1">彖传注 <a class="header-anchor" href="#彖传注" aria-label="Permalink to “彖传注”">​</a></h2><p>虞翻曰：位窮於上，故止也。</p><p>虞翻曰：時止謂上陽窮止，故止。時行謂三體處震，為行也。</p><p>虞翻曰：動謂三，靜謂上。艮止則止，震行則行，故不失時。五動成離，故其道光明。</p><p>虞翻曰：謂兩象各止其所。</p><p>虞翻曰：艮其背，背也。兩象相背，故不相與也。</p><p>案：其義已見繇辭也。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：兼山艮。君子以思不出其位。</p><h2 id="象传注" tabindex="-1">象传注 <a class="header-anchor" href="#象传注" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：君子謂三也。三君子位。震為出。坎為隱伏，為思，故｢以思不出其位｣也。</p><h2 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h2><p>初六，艮其趾，無咎，利永貞。</p><h2 id="初六注" tabindex="-1">初六注 <a class="header-anchor" href="#初六注" aria-label="Permalink to “初六注”">​</a></h2><p>虞翻曰：震為趾，故艮其趾矣。失位變得正故｢無咎，永貞｣也。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：艮其趾，未失正也。</p><h2 id="象传注-1" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-1" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：動而得正故｢未失正也｣。</p><h2 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h2><p>六二，艮其腓，不拯其隨，其心不快。</p><h2 id="六二注" tabindex="-1">六二注 <a class="header-anchor" href="#六二注" aria-label="Permalink to “六二注”">​</a></h2><p>虞翻曰：巽長，為股。艮小，為腓。拯，取也。隨謂下二陰，艮為止，震為動，故｢不拯其隨｣。坎為心，故｢其心不快｣。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：不拯其隨，未退聽也。</p><h2 id="象传注-2" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-2" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：坎為耳，故｢未退聽也｣。</p><h2 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h2><p>九三，艮其限，裂其夤，厲閽心。</p><h2 id="九三注" tabindex="-1">九三注 <a class="header-anchor" href="#九三注" aria-label="Permalink to “九三注”">​</a></h2><p>虞翻曰：限，腰帶處也。坎為腰。五來之三，故｢艮其限｣。夤，脊肉。艮為背，坎為脊；艮為手。震起艮止，故｢裂其夤｣。坎為心。厲，危也。艮為閽。閽，守門人。坎盜動門，故｢厲閽心｣。古閽作熏字。馬因言熏灼其心，未聞易道以坎水熏灼人也。荀氏以熏為勳或誤作動。皆非也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：艮其限，危閽心也。</p><h2 id="象传注-3" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-3" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：坎為心，坎盜動門，故｢危閽心也｣。</p><h2 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h2><p>六四，艮其身，無咎。</p><h2 id="六四注" tabindex="-1">六四注 <a class="header-anchor" href="#六四注" aria-label="Permalink to “六四注”">​</a></h2><p>虞翻曰：身，腹也。觀坤為身，故｢艮其身｣。得位承五，故無咎。或謂妊身也。五動則四體離婦。離為大腹，孕之象也，故｢艮其身｣。得正承五，而受陽施，故無咎。《詩》曰：大任有身，生此文王也。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：艮其身，止諸躬也。</p><h2 id="象传注-4" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-4" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：艮為止，五動乘四則妊身，故｢止諸躬也｣。</p><h2 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h2><p>六五，艮其輔，言有孚，悔亡。</p><h2 id="六五注" tabindex="-1">六五注 <a class="header-anchor" href="#六五注" aria-label="Permalink to “六五注”">​</a></h2><p>虞翻曰：輔面頰骨，上頰車者也。三至上，體頤象，艮為止，在坎車上。故｢艮其輔｣。謂輔車相依。震為言。五失位悔也。動得正，故｢言有孚，悔亡｣也。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：艮其輔，以中正也。</p><h2 id="象传注-5" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-5" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：五動之中，故｢以正中也｣。</p><h2 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h2><p>上九：敦艮，吉。</p><h2 id="上九注" tabindex="-1">上九注 <a class="header-anchor" href="#上九注" aria-label="Permalink to “上九注”">​</a></h2><p>虞翻曰：無應靜止，下據二陰，故｢敦艮，吉｣也。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：敦艮之吉，以厚終也。</p><h2 id="象传注-6" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-6" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：坤為厚，陽上據坤，故｢以厚終也｣。</p>',71)])])}const m=e(l,[["render",n]]);export{b as __pageData,m as default};
